  'settings.magicPrompts.page.group.sessionSummary.title': 'Session Özeti',
  'settings.magicPrompts.page.group.sessionSummary.description': '/summary slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Yıkıcı değildir - session geçmişini sıkıştırmaz.',
  'settings.magicPrompts.page.group.sessionWorkspaceReview.title': 'Çalışma Alanı İncelemesi',
  'settings.magicPrompts.page.group.sessionExplore.title': 'Kod Tabanı Turu',
  'settings.magicPrompts.page.group.sessionExplore.description': '/explore slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Depoyu inceler ve yapılandırılmış bir yönlendirme sunar — büyük resim, ana modüller, nasıl bağlandıkları ve nereden başlanacağı — dosya dosya bir döküm yerine.',
  'settings.magicPrompts.page.group.sessionWorkspaceReview.description': '/workspace-review slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Çalışma alanı diff\'ini amacına ulaşıp ulaşmadığı ve doğru, yeterli olup olmadığı açısından inceler; bulguları önem derecesine göre sınıflandırır.',
  'settings.magicPrompts.page.group.sessionFeaturePlan.title': 'Özellik Planlaması',
  'settings.magicPrompts.page.group.sessionFeaturePlan.description': '/plan-feature slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Kodu araştıran ve bir uygulama planı üretmeden önce netleştirici soruları küçük gruplar halinde soran rehberli bir diyalog yürütür.',
  'settings.magicPrompts.page.group.sessionCatchUp.title': 'Son Durumu Yakala',
  'settings.magicPrompts.page.group.sessionCatchUp.description': '/catch-up slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Ne yaptığınızı anlamak için branch\'e duyarlı bağlam oluşturur — branch\'in commit\'leri, PR\'i ve commit\'lenmemiş çalışmalar bir arada — ardından anlaşılır bir özet ve ürüne odaklı bir sonraki adım sunar.',
  'settings.magicPrompts.page.group.sessionDebug.title': 'Hata Ayıklama',
  'settings.magicPrompts.page.group.sessionDebug.description': '/debug slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Rehberli bir kök neden incelemesi yürütür — belirtiyi kaydeder, hipotezler kurar, bunları koda karşı sınar ve bir düzeltme önermeden önce nedeni doğrular.',
  'settings.magicPrompts.page.group.sessionWeigh.title': 'Seçenekleri Değerlendir',
  'settings.magicPrompts.page.group.sessionWeigh.description': '/weigh slash komutunun kullandığı prompt\'lar: görünür kullanıcı mesajı + gizli talimatlar. Kodu inceler, ardından her biri ödünleşimleri ve bir öneriyle birlikte 2-3 farklı yaklaşım ortaya koyar — plan veya kod yazmadan.',
  'settings.magicPrompts.page.group.sessionFusion.title': 'Füzyon',
